<?php declare(strict_types=1); require __DIR__.'/_bootstrap.php'; require_admin(); if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);exit;} verify_csrf($_GET['csrf']??'');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if($id){$q=$pdo->prepare('SELECT media_path,thumbnail_path FROM gallery_media WHERE id=?');$q->execute([$id]);$r=$q->fetch();if($r){$d=$pdo->prepare('DELETE FROM gallery_media WHERE id=?');$d->execute([$id]);delete_upload($r['media_path']);delete_upload($r['thumbnail_path']);flash('success','Media deleted.');}}redirect_to('media.php');
